class Solution:
    def networkDelayTime(self, times: List[List[int]], n: int, k: int) -> int:
        # given a network of n directed nodes, labeled from 1 to n. 
        # You are also given times, a list of directed edges where times[i] = (ui, vi, ti)
            # ui is the src node
            # vi is the dest node
            # ti is the time it takes for a signal to travel from the source to the target node
        
        # we do dijkstra's alg
        # for convience make it so we don't need -1 to index into dist
        dist = [float('inf')] * (n + 1)
        visited = set()
        # construct our adj list         
        adj = defaultdict(list)
        for src, dest, time in times:
            # if src not in adj:
            #     adj[src] = []
            adj[src].append((dest, time))
        # print(adj)
        # node 0 doesn't exist 
        dist[0] = 0

        # set up our djk to start at k
        dist[k] = 0

        # set curr = k and dist[k - 1] = 0 since we are starting at k. Set everyone else to inf
        # for every curr:
            # set curr as visited
            # look at all the neighbors and calculate the dist to the neighbor when we just came from curr
            # save it into dist[neighbors - 1] if it ends up being less than dist[neighbors - 1]
            # traverse to the neighbor that had the shortest calculated dist and wasn't visited alr
            
            # print(minDist)
            # print(next)
        # print(adj)
        heap = []
        heapq.heappush(heap, (0, k))
        while heap:
            
            c_dist, curr = heapq.heappop(heap)
            print(curr)
            if curr in visited:
                continue
            
            visited.add(curr)
            
            for neighbor, time in adj[curr]:
                n_dist = dist[curr] + time
                dist[neighbor] = min(dist[neighbor], n_dist)
                heapq.heappush(heap, (dist[neighbor], neighbor))

        # print(dist)
        if float('inf') in dist:
            return -1
        else:
            return max(dist)



